// GTW BDO — Logo Patch v1.0
// Tambahkan file ini ke index.html sebelum </body>:
// <script src="logo_patch.js"></script>
(function() {
  // 1. Ganti favicon tab browser
  document.querySelectorAll("link[rel*='icon']").forEach(function(el) { el.remove(); });
  var favicon = document.createElement('link');
  favicon.rel = 'shortcut icon';
  favicon.type = 'image/jpeg';
  favicon.href = 'data:image/jpeg;base64,';
  document.head.appendChild(favicon);

  // 2. Ganti ikon di sidebar brand
  var brandIconDiv = document.querySelector('.sidebar-brand-icon');
  if (brandIconDiv) {
    brandIconDiv.style.cssText += 'background:transparent !important; padding:0 !important; border-radius:50%; overflow:hidden; width:36px; height:36px; flex-shrink:0;';
    brandIconDiv.innerHTML = '<img src="data:image/jpeg;base64," style="width:36px;height:36px;border-radius:50%;object-fit:cover;display:block;" alt="GTW BDO Logo">';
  }
})();
